function Menu({ navigation, header, scrollToPage, activeScreen, setActiveScreen }) {
    const [showMenu, setShowMenu] = useState(false);

    const openMenu = () => setShowMenu(true);
    const closeMenu = () => setShowMenu(false);


    const handleNavigation = useCallback((screenName, index) => {
        setActiveScreen(screenName);
        scrollToPage(index);
    }, [scrollToPage, setActiveScreen]);

    return (<View>
        <Modal
            testID={'modal'}
            deviceHeight={Dimensions.get('window').height}
            deviceWidth={Dimensions.get('window').width}
            animationIn="slideInLeft"
            animationOut="slideOutLeft"
            transparent
            isVisible={showMenu}
            onRequestClose={closeMenu}
            style={{
                width: Dimensions.get('window').width,
                height: Dimensions.get('window').height,
                flexDirection: 'row',
                margin: 0,
            }}
        >
            <View
                style={{
                    backgroundColor: '#000',
                    width: Dimensions.get('window').width * 0.3,
                    height: Dimensions.get('window').height,
                    flexDirection: 'column',
                }}
            >
                <View style={{ flex: 3 }}>
                    <TouchableOpacity
                        onPress={() => {
                            closeMenu();
                        }}
                        style={{
                            marginTop: 5,
                            borderRadius: 5,
                            backgroundColor: '#222',
                            height: 30,
                            width: Dimensions.get('window').width * 0.3,
                            justifyContent: 'center',
                            alignItems: 'center',
                            maxWidth: 200,
                            alignSelf: 'center',
                        }}
                    >
                        <Text style={{ color: '#FFF' }}>
                            Close
                        </Text>
                    </TouchableOpacity>
                    <TouchableOpacity
                        onPress={() => {
                            closeMenu();
                            navigation.navigate('Main');
                            navigation.navigate('ProfileSettings');
                        }}
                        style={{
                            marginTop: 5,
                            borderRadius: 5,
                            backgroundColor: '#111',
                            height: 50,
                            width: Dimensions.get('window').width * 0.3,
                            justifyContent: 'center',
                            alignItems: 'center',
                            alignSelf: 'center',
                            maxWidth: 200
                        }}
                    >
                        <Text style={{ color: '#fff' }}>Settings</Text>
                    </TouchableOpacity>



                    <TouchableOpacity
                        onPress={() => {
                            closeMenu();
                            navigation.navigate('Main');
                            navigation.navigate('Profile', { userId: null }); // null означает профиль текущего пользователя
                        }}
                        style={{
                            marginTop: 5,
                            borderRadius: 5,
                            backgroundColor: '#111',
                            height: 50,
                            width: Dimensions.get('window').width * 0.3,
                            justifyContent: 'center',
                            alignItems: 'center',
                            alignSelf: 'center',
                            maxWidth: 200
                        }}
                    >
                        <Text style={{ color: '#fff' }}>Profile</Text>
                    </TouchableOpacity>




                </View>
                <View style={{ flex: 10 }}></View>
                <View style={{ flex: 1, alignSelf: 'center', alignItems: 'center' }}>
                    <Text style={{ color: '#FFF' }}>
                        SigmaLTD community
                    </Text>
                    <Text style={{ color: '#555' }}>
                        We trust in you
                    </Text>
                </View>

            </View>
            <TouchableOpacity
                style={{
                    width: Dimensions.get('window').width * 0.7, height: Dimensions.get('window').height,
                }}
                onPress={closeMenu}
            />
        </Modal>
        <View style={{ flexDirection: 'row', backgroundColor: '#000', width: Dimensions.get('window').width }}>

            {header ? <>
                <Pressable
                    style={{
                        flex: 2, alignItems: 'center', alignSelf: 'center', justifyContent: 'center',
                    }}
                    onPress={openMenu}
                >
                    <Text style={{ fontSize: 30, color: "#FFF", fontWeight: "bold" }}>Σ</Text>
                </Pressable>
                <View
                    style={{
                        flex: 20, alignItems: 'center', alignSelf: 'center', justifyContent: 'center',
                    }} />
                <TouchableOpacity onPress={navigation.goBack}
                    style={{ flex: 2, justifyContent: 'center', alignItems: 'center', marginRight: 5 }}>
                    <Text style={{ color: "#FFF" }}>Close</Text>
                </TouchableOpacity>

            </> : <>
                <Pressable
                    style={{
                        flex: 2, alignItems: 'center', alignSelf: 'center', justifyContent: 'center',
                    }}
                    onPress={openMenu}
                >
                    <Text style={{ fontSize: 30, color: "#FFF", fontWeight: "bold" }}>Σ</Text>
                </Pressable>
                <TouchableOpacity
                    style={{
                        flex: 10, alignItems: 'center', justifyContent: 'center',
                    }}
                    onPress={() => handleNavigation('Feed', 0)}
                >
                    <Text
                        style={{
                            fontSize: activeScreen === 'Feed' ? 20 : 16,
                            fontWeight: activeScreen === 'Feed' ? 'bold' : 'normal',
                            color: "#FFF"
                        }}
                    >
                        Feed
                    </Text>
                </TouchableOpacity><TouchableOpacity
                    style={{
                        flex: 10, alignItems: 'center', justifyContent: 'center',
                    }}
                    onPress={() => handleNavigation('Following', 1)}
                >
                    <Text
                        style={{
                            fontSize: activeScreen === 'Following' ? 20 : 16,
                            fontWeight: activeScreen === 'Following' ? 'bold' : 'normal',
                            color: "#FFF"
                        }}
                    >
                        Following
                    </Text>
                </TouchableOpacity>
                <View
                    style={{
                        flex: 2, alignItems: 'center', alignSelf: 'center', justifyContent: 'center',
                    }}>
                </View>
            </>}
        </View>
    </View>);
}

