function UserProfileModal({ isVisible, onClose, user, navigation }) {
    const [stats, setStats] = useState(null);
    const [loadingStats, setLoadingStats] = useState(false);

    useEffect(() => {
        if (isVisible && user) {
            fetchUserStats();
        }
    }, [isVisible, user]);

    const fetchUserStats = async () => {
        if (!user?.idUser) return;

        try {
            setLoadingStats(true);
            const response = await fetch(`${Database.API_URL}/user/${user.idUser}/stats`, {
                headers: await Database.authHeaders(),
            });

            if (response.ok) {
                const statsData = await response.json();
                setStats(statsData);
            }
        } catch (error) {
            console.error('Error fetching user stats:', error);
        } finally {
            setLoadingStats(false);
        }
    };

    if (!user) return null;

    const handleVisitProfile = () => {
        onClose();
        navigation.navigate('Profile', { userId: user.idUser });
    };

    return (
        <Modal
            isVisible={isVisible}
            onBackdropPress={onClose}
            onBackButtonPress={onClose}
            style={styles.modal}
            animationIn="fadeIn"
            animationOut="fadeOut"
        >
            <View style={styles.modalContent}>
                {/* Header */}
                <View style={styles.header}>
